```let g:win = -1
function! Openfloat() abort
        let buf = nvim_create_buf(v:false, v:true)
        call nvim_buf_set_lines(buf, 0, -1, v:true, ["(r) rename", "(d) doHover", "(j) jumpDefinition", "(q) quit"])
        let opts = {'relative': 'cursor', 'anchor': 'NW', 'style': 'minimal', 'width': 30, 'height': 6, 'col': 0, 'row': 1}
        let g:win = nvim_open_win(buf, v:true, opts)

        nnoremap &lt;plug&gt;(quit) :call nvim_win_close(g:win, v:true)&lt;cr&gt;
        nmap &lt;buffer&gt; q &lt;plug&gt;(quit)
        nmap &lt;buffer&gt; r &lt;plug&gt;(quit):call CocAction('rename')&lt;cr&gt;
        nmap &lt;buffer&gt; d &lt;plug&gt;(quit):call CocAction('doHover')&lt;cr&gt;
        nmap &lt;buffer&gt; j &lt;plug&gt;(quit):call CocAction('jumpDefinition','split')&lt;cr&gt;
endfunction
nnoremap ff :call Openfloat()&lt;cr&gt;```
